package io.github.kechankrisna.wing.onlinepayment

/** Where Wing sends the payer after paying (`integration_type`). */
public enum class WingIntegrationType(
    /** the value sent to Wing */
    public val value: String,
) {
    /** back to `return_url` in the browser (Wing's default) */
    WEB_APP("WEBAPP"),

    /** back into your app through the deep link you registered with Wing */
    MOBILE_APP("MOBAPP"),
}

/**
 * Payment to authorize. `rand_str` and `timestamp` are generated by the SDK;
 * every optional field is sent only when set.
 *
 * @property orderReferenceNo your unique order id (`order_reference_no`)
 * @property amount amount to pay, at most 2 decimals; sent as `15.00`
 * @property returnUrl Wing redirects the payer here (GET) after paying, with
 *   `?status=success&token=...`
 * @property cancelUrl Wing redirects the payer here (GET) when they cancel
 * @property integrationType [WingIntegrationType.WEB_APP] (default) or
 *   [WingIntegrationType.MOBILE_APP] for the deep link back to your app
 * @property isWingAppInstalled whether the Wing Bank app is on the payer's
 *   phone (`is_wingapp_installed`)
 * @property itemName remark of the product or item, max 255 characters
 * @property merchantName name shown to the payer; Wing shows your registered
 *   name without it
 * @property wingAccount Wing account filled in for the payer
 */
public data class WingPayment(
    public val orderReferenceNo: String,
    public val amount: Number,
    public val returnUrl: String,
    public val cancelUrl: String,
    public val integrationType: WingIntegrationType = WingIntegrationType.WEB_APP,
    public val isWingAppInstalled: Boolean = false,
    public val itemName: String? = null,
    public val merchantName: String? = null,
    public val wingAccount: String? = null,
)
